<?php
namespace SMF\Setup;
if (PHP_SAPI !== 'cli' && (get_included_files()[0] ?? '') === __FILE__) { http_response_code(404); exit; }
require_once __DIR__.'/Installer.php';
require_once dirname(__DIR__).'/core/Security.php';

final class WebWizard {
    private string $error='';
    public function __construct(private Installer $installer) {}
    private static function e(mixed $s):string{return htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
    private function field(string $key,string $label,string $type='text',string $default='',bool $required=false):void{
        $v=$_SESSION['setup']['input']??[];$value=$v;
        foreach(explode('.',$key)as$part)$value=is_array($value)?($value[$part]??null):null;
        $value??=$default;$name=str_contains($key,'.')?str_replace('.','[',$key).']':$key;$secret=$type==='password';
        echo '<label>'.self::e($label).'<input name="'.self::e($name).'" type="'.$type.'" value="'.self::e($secret?'':$value).'"'.($secret&&$value!==''?' placeholder="Bereits eingegeben – leer lassen zum Beibehalten"':'').($required&&!($secret&&$value!=='')?' required':'').' maxlength="4096"'.($secret?' autocomplete="new-password"':'').'></label>';
    }
    private function remember(array $keys):void{
        foreach($keys as$key){$value=$_POST[$key]??'';if(is_array($value)||!is_string($value)||strlen($value)>4096)throw new \InvalidArgumentException('Ungültige Formulareingabe.');if(str_contains($key,'password')&&$value===''&&!empty($_SESSION['setup']['input'][$key]))continue;$_SESSION['setup']['input'][$key]=$value;}
    }
    public function run():void{
        ini_set('display_errors','0');ini_set('zend.exception_ignore_args','1');umask(0077);
        header('Cache-Control: private, no-store');header('Referrer-Policy: no-referrer');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header("Content-Security-Policy: default-src 'self'; style-src 'self'; img-src 'self'; form-action 'self'; frame-ancestors 'none'; base-uri 'none'");
        if(!\HttpSecurity::isHttps() && !(PHP_SAPI==='cli-server'&&in_array($_SERVER['REMOTE_ADDR']??'',['127.0.0.1','::1'],true))){http_response_code(426);$this->page('HTTPS erforderlich','<p>Den Installationsassistenten über die HTTPS-Adresse des Shops öffnen.</p>');return;}
        if(!in_array($_SERVER['REQUEST_METHOD']??'GET',['GET','POST'],true)){http_response_code(405);return;}
        if(!$this->installer->available()){http_response_code(409);$this->page('Bereits eingerichtet','<p>Diese Installation ist konfiguriert. Der Assistent kann sie nicht überschreiben.</p><a href="/src/">Zur Verwaltung</a>');return;}
        $temp=sys_get_temp_dir().'/smf-setup-'.substr(hash('sha256',$this->installer->keyFile()),0,24);
        if(is_link($temp)||(!is_dir($temp)&&!mkdir($temp,0700))||!chmod($temp,0700))throw new \RuntimeException('Geschützter Installationsspeicher nicht verfügbar.');
        session_name('smf_setup');ini_set('session.use_strict_mode','1');ini_set('session.use_only_cookies','1');ini_set('session.gc_maxlifetime','1800');ini_set('session.gc_probability','1');ini_set('session.gc_divisor','1');session_save_path($temp);session_set_cookie_params(['lifetime'=>0,'path'=>'/setup.php','secure'=>\HttpSecurity::isHttps(),'httponly'=>true,'samesite'=>'Strict']);session_start();
        if(($_SESSION['setup']['expires']??0)<time())$_SESSION=[];
        $_SESSION['csrf_token']??=bin2hex(random_bytes(32));$_SESSION['setup']['expires']=time()+1800;
        $step=(int)($_SESSION['setup']['step']??0);
        try{
            if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
                if(!is_string($_POST['csrf_token']??null)||!hash_equals($_SESSION['csrf_token'],$_POST['csrf_token'])){http_response_code(403);throw new \InvalidArgumentException('Formularfreigabe fehlt. Seite neu laden.');}
                if($step===0){$this->checkAuthLimit($temp);$token=$_POST['setup_token']??'';if(!is_string($token)||!$this->installer->authorized($token)){$this->failedAuth($temp);http_response_code(403);throw new \InvalidArgumentException('Startschlüssel fehlt, ist ungültig oder älter als 24 Stunden.');}session_regenerate_id(true);$_SESSION['setup']['owner']=hash('sha256',$token);$_SESSION['setup']['step']=$step=1;}
                else{
                    $token=$this->installer->token();
                    if(!$this->installer->authorized($token)||!hash_equals($_SESSION['setup']['owner']??'',hash('sha256',$token)))throw new \RuntimeException('Installationsfreigabe abgelaufen.');
                    if(($_POST['back']??'')==='1'){$_SESSION['setup']['step']=$step=max(1,$step-1);}
                    elseif($step===1){$this->remember(['private_dir','db_type','db_host','db_port','db_name','db_user','db_password','db_socket']);$_SESSION['setup']['step']=$step=2;}
                    elseif($step===2){$this->remember(['site_url','site_name','support_email','system_email','admin_name','admin_email','admin_password','mail_mode','smtp_host','smtp_port','smtp_user','smtp_password']);$password=$_SESSION['setup']['input']['admin_password']??'';if(!is_string($_POST['admin_password_confirm']??null)||!hash_equals($password,$_POST['admin_password_confirm']))throw new \InvalidArgumentException('Passwortbestätigung stimmt nicht überein.');$_SESSION['setup']['step']=$step=3;}
                    elseif($step===3){foreach(['ispconfig','ogp']as$id){$row=$_POST[$id]??[];if(!is_array($row))throw new \InvalidArgumentException('Ungültige Panelangaben.');foreach(['url','username','password','token','ca_file','local_root','server_id']as$key){$value=$row[$key]??($key==='server_id'?'1':'');if(!is_string($value)||strlen($value)>4096)throw new \InvalidArgumentException('Ungültige Panelangaben.');if(in_array($key,['password','token'],true)&&$value===''&&!empty($_SESSION['setup']['input'][$id][$key]))continue;$_SESSION['setup']['input'][$id][$key]=$value;}}$_SESSION['setup']['report']=$this->installer->inspect($_SESSION['setup']['input']);$_SESSION['setup']['step']=$step=4;}
                    elseif($step===4){$_SESSION['setup']['input']['modules']=$_POST['modules']??[];$_SESSION['setup']['report']=$this->installer->inspect($_SESSION['setup']['input']);$_SESSION['setup']['step']=$step=5;}
                    elseif($step===5){$input=$_SESSION['setup']['input'];$input['allow_unverified']=($_POST['allow_unverified']??'')==='1';$report=$this->installer->install($input,$token);$_SESSION=[];session_destroy();$this->page('Installation abgeschlossen',$this->completed($report));return;}
                }
            }
        }catch(\Throwable $error){$safe=in_array(get_class($error),[\InvalidArgumentException::class,\RuntimeException::class],true)&&in_array(basename($error->getFile()),['WebWizard.php','Installer.php','ProviderDetector.php'],true);$this->error=$safe?$error->getMessage():'Installation gestoppt. Das private Installationsjournal bleibt für eine Wiederaufnahme erhalten.';error_log('Shop setup: '.get_class($error).' at '.basename($error->getFile()).':'.$error->getLine());file_put_contents($temp.'/last-error.json',json_encode(['class'=>get_class($error),'file'=>basename($error->getFile()),'line'=>$error->getLine()]),LOCK_EX);}
        $this->render($step);
    }
    private function failedAuth(string $dir):void{
        $path=$dir.'/attempts-'.hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown').'.json';if(is_link($path))throw new \RuntimeException('Anfragesperre ungültig.');$file=fopen($path,'c+');if(!$file||!flock($file,LOCK_EX))throw new \RuntimeException('Anfragebegrenzung nicht verfügbar.');
        try{$s=json_decode(stream_get_contents($file),true)?:['at'=>time(),'count'=>0];if($s['at']<time()-900)$s=['at'=>time(),'count'=>0];$s['count']++;rewind($file);ftruncate($file,0);fwrite($file,json_encode($s));fflush($file);if($s['count']>10){http_response_code(429);throw new \RuntimeException('Zu viele Versuche. Nach 15 Minuten erneut versuchen.');}}finally{flock($file,LOCK_UN);fclose($file);}
    }
    private function checkAuthLimit(string $dir):void{
        $path=$dir.'/attempts-'.hash('sha256',$_SERVER['REMOTE_ADDR']??'unknown').'.json';
        if(is_link($path))throw new \RuntimeException('Anfragesperre ungültig.');
        if(is_file($path)){$s=json_decode(file_get_contents($path),true);if(($s['at']??0)>=time()-900&&($s['count']??0)>=10){http_response_code(429);throw new \RuntimeException('Zu viele Versuche. Nach 15 Minuten erneut versuchen.');}}
    }
    private function page(string $title,string $content):void{echo '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>'.self::e($title).' – Shopinstallation</title><link rel="stylesheet" href="/public/assets/setup-wizard.css"></head><body><main><p class="eyebrow">Server Management Framework · Shop</p><h1>'.self::e($title).'</h1>'.$content.'</main></body></html>';}
    private function completed(array $report):string{return '<p>Der Shop ist eingerichtet. Ein eigenes Administratorkonto und '.count($report['modules']).' ausgewählte Module sind angelegt. Die Installation ist gesperrt.</p><p><a class="button" href="/src/login.php">Zur Verwaltung</a> <a href="/">Shop öffnen</a></p><h2>Für den laufenden Betrieb</h2><ol><li>Im Hosting-Scheduler jede Minute <code>php /absoluter/shop-pfad/bin/worker.php --limit=10 --retain-days=90</code> ausführen. Der Assistent hat keinen Cronjob eingerichtet.</li><li>Mailversand mit einer eigenen Testadresse prüfen und Betreiber-/Vertragsangaben vervollständigen.</li><li>Produkte, Zahlungsanbieter und Provider-Zuordnungen in der Verwaltung einrichten. OGP-Verbindung und Gameserver-Bereitstellung besitzen getrennte Freigaben.</li></ol><p>Sandbox ist aktiv. Die separate Freigabe von Liveoperationen erfolgt in der privaten Betreiberkonfiguration.</p>';}
    private function render(int $step):void{
        ob_start();if($this->error!=='')echo '<p class="error" role="alert">'.self::e($this->error).'</p>';
        echo '<p>Schritt '.($step+1).' von 6</p><form method="post" action="/setup.php"><input type="hidden" name="csrf_token" value="'.self::e($_SESSION['csrf_token']).'">';
        if($step===0){echo '<p>Den Startschlüssel aus <code>config/setup-access.php</code> eingeben. Mit SSH erzeugt <code>php bin/setup.php --prepare</code> diese Datei. Bei FTP-Zugang <code>config/setup-access.example.php</code> kopieren und den Platzhalter durch eine zufällige Zeichenfolge mit mindestens 32 Zeichen ersetzen. Die Datei verweigert ihren HTTP-Aufruf selbst und wird nach der Installation entfernt.</p>';$this->field('setup_token','Startschlüssel','password','',true);echo '<p>Der Assistent richtet eine neue, leere Installation ein. Für einen vorhandenen Shop ist der dokumentierte Upgradeweg vorgesehen.</p>';}
        elseif($step===1){echo '<h2>System und Datenbank</h2><p>PHP '.self::e(PHP_VERSION).'. Verfügbare PDO-Treiber: '.self::e(implode(', ',(class_exists('PDO')?\PDO::getAvailableDrivers():[]))).'. Der private Speicher muss außerhalb des Webroots liegen.</p>';$root=dirname(dirname($this->installer->keyFile()));$parent=dirname($root);$default=is_dir($parent.'/private')&&is_writable($parent.'/private')?$parent.'/private/smf-'.basename($root):$parent.'/.smf-private/'.substr(hash('sha256',$root),0,16);$this->field('private_dir','Privater Speicherordner','text',$default,true);$current=$_SESSION['setup']['input']['db_type']??'mysql';echo '<label for="setup-db-type">Datenbanksystem</label><select id="setup-db-type" name="db_type"><option value="mysql"'.($current==='mysql'?' selected':'').'>MySQL / MariaDB</option><option value="sqlite"'.($current==='sqlite'?' selected':'').'>SQLite</option></select><p>Bei SQLite entsteht die Datenbank im privaten Speicher. Die folgenden Zugangsfelder gelten für MySQL/MariaDB.</p>';$this->field('db_host','Datenbankhost','text','localhost');$this->field('db_port','Datenbankport','number','3306');$this->field('db_name','Name der leeren Datenbank');$this->field('db_user','Datenbankbenutzer');$this->field('db_password','Datenbankpasswort','password');echo '<details><summary>Erweiterte Datenbankangaben</summary>';$this->field('db_socket','Optionaler Unix-Socket');echo '</details>';}
        elseif($step===2){echo '<h2>Shop und Administrator</h2>';$this->field('site_name','Shopname','text','Mein Shop',true);$this->field('site_url','HTTPS-Adresse der Shopdomain','url','',true);$this->field('support_email','Supportadresse','email','',true);$this->field('system_email','E-Mail-Absender','email','',true);$this->field('admin_name','Administratorname','text','',true);$this->field('admin_email','Administrator-E-Mail','email','',true);$this->field('admin_password','Administratorpasswort – mindestens 12 Zeichen','password','',true);$this->field('admin_password_confirm','Passwort bestätigen','password','',true);$current=$_SESSION['setup']['input']['mail_mode']??'system';echo '<h2>Mailversand</h2><label for="setup-mail-mode">Verfahren</label><select id="setup-mail-mode" name="mail_mode"><option value="system"'.($current==='system'?' selected':'').'>Maildienst des Webservers</option><option value="smtps"'.($current==='smtps'?' selected':'').'>SMTP mit direktem TLS (SMTPS)</option></select><p>SMTPS verwendet gewöhnlich Port 465. Die Versandprüfung erfolgt nach der Einrichtung.</p>';$this->field('smtp_host','SMTPS-Host');$this->field('smtp_port','SMTPS-Port','number','465');$this->field('smtp_user','SMTPS-Benutzer');$this->field('smtp_password','SMTPS-Passwort','password');}
        elseif($step===3){echo '<h2>Vorhandene Panels erkennen</h2><p>Die Panels können auf diesem oder einem anderen Server laufen. Die Prüfung verändert keine Hosting- oder Gameserverressourcen. Ein unerreichbares Panel bleibt als ungeprüft erkennbar.</p>';foreach(['ispconfig'=>'ISPConfig','ogp'=>'OpenGamePanel']as$id=>$label){echo '<fieldset><legend>'.$label.'</legend>';$this->field($id.'.url','Basisadresse (optional)','url');if($id==='ispconfig'){$this->field($id.'.username','Remote-Benutzer');$this->field($id.'.password','Remote-Passwort','password');$this->field($id.'.server_id','Server-ID','number','1');}else{$this->field($id.'.token','Vorhandener Betreiber-API-Token','password');echo '<p>Der Token wird ausschließlich im POST-Body geprüft. Eine erfolgreiche Prüfung aktiviert den bestehenden Frameworkzugang. Automatische Gameserverbestellungen folgen mit dem eigenen Gameservermodul.</p>';}echo '<details><summary>Eigene Zertifizierungsstelle und lokaler Installationspfad</summary>';$this->field($id.'.ca_file','Optionaler Pfad zur CA-Datei');$this->field($id.'.local_root','Optionaler lokaler Panel-Webroot');echo '</details></fieldset>';}}
        elseif($step===4){echo '<h2>Shopmodule auswählen</h2><p>Katalog, Kundenportal und Anfragen bilden die Shopbasis. Benötigte Abhängigkeiten werden gemeinsam eingerichtet.</p>';$names=['shop.storage'=>'Gemeinsame Speicherung','shop.catalog'=>'Katalog und Konfigurator','shop.portal'=>'Kundenportal und Support','shop.orders'=>'Anfragen, Angebote und Bestellungen','shop.payments'=>'Zahlungen','shop.provisioning'=>'Hosting-/VPS-Bereitstellung','shop.billing'=>'Rechnungen und PDF','shop.contracts'=>'Verträge und Kündigungen','shop.communications'=>'Nachrichten und FAQ','shop.promotions'=>'Gutscheine','shop.subscriptions'=>'Erweiterungen und Abos'];$selected=$_SESSION['setup']['input']['modules']??['shop.billing','shop.contracts','shop.communications'];foreach($names as$id=>$label){$base=in_array($id,['shop.storage','shop.catalog','shop.portal','shop.orders'],true);echo '<label class="choice"><input type="checkbox" name="modules[]" value="'.$id.'"'.($base||in_array($id,$selected,true)?' checked':'').($base?' disabled':'').'>'.self::e($label).($base?' (Basis)':'').'</label>';}}
        else{echo '<h2>Prüfergebnis und Einrichtung</h2>';$report=$_SESSION['setup']['report']??[];foreach(['ispconfig'=>'ISPConfig','ogp'=>'OpenGamePanel']as$id=>$label){$p=$report['providers'][$id]??[];echo '<section><h3>'.$label.'</h3><p>'.self::e($report['local'][$id]['message']??'').'</p><p>'.self::e($p['message']??'').'</p></section>';}echo '<p>'.count($report['modules']??[]).' Module · Datenbank '.self::e($report['database']??'').' · Sandbox</p><p>Jetzt werden Schema und Module angelegt, das Administratorkonto erstellt und die Konfiguration im privaten Speicher aktiviert.</p><label class="choice"><input type="checkbox" name="allow_unverified" value="1">Bei fehlgeschlagener Panelprüfung den Shop mit deaktivierter betroffener Anbindung einrichten.</label>';}
        echo '<div class="actions">'.($step>1?'<button type="submit" name="back" value="1" formnovalidate>Zurück</button>':'').'<button type="submit">'.($step===5?'Shop installieren':($step===3?'Verbindungen prüfen':'Weiter')).'</button></div></form>';
        $this->page('Shop installieren',ob_get_clean());
    }
}
